from pickle import PickleBuffer

def _t():
    try:
        PickleBuffer()
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    try:
        PickleBuffer('foo')
    except TypeError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
    m = memoryview(b'foo')
    m.release()
    try:
        PickleBuffer(m)
    except ValueError as _exc:
        pass
    else:
        raise AssertionError('assertRaises: did not raise')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

